import{_ as n,o as a,c as h,a5 as i}from"./chunks/framework.Bf1r8NYr.js";const l=JSON.parse('{"title":"Nhập môn và cách học","description":"","frontmatter":{},"headers":[],"relativePath":"course/module-0-intro/index.md","filePath":"course/module-0-intro/index.md"}'),o={name:"course/module-0-intro/index.md"};function c(r,t,s,d,e,g){return a(),h("div",null,[...t[0]||(t[0]=[i(`<h1 id="nhap-mon-va-cach-hoc" tabindex="-1">Nhập môn và cách học <a class="header-anchor" href="#nhap-mon-va-cach-hoc" aria-label="Permalink to &quot;Nhập môn và cách học&quot;">​</a></h1><p><strong>Mục tiêu duy nhất của phần này:</strong> sau khi học xong, bạn nắm được <strong>workflow quản lý dữ liệu từ thiết kế đề cương đến kết thúc nghiên cứu</strong> và trả lời được “ở bước này phải làm gì, vì sao, và làm sai thì hậu quả gì”.</p><p><strong>Đối tượng:</strong> sinh viên BME, bác sĩ và nghiên cứu viên mới bắt đầu. Không cần biết lập trình. <strong>Thời lượng:</strong> khoảng 2–3 phút đọc mỗi bài + quiz (tổng khoảng 1 giờ), 6 bài. <strong>Nguồn:</strong> tổng hợp từ bản <em>Tổng hợp literature review — RDM Y Sinh</em> (20/11/2026). Có 103 mục tham khảo, trong đó một số đang chờ kiểm chứng (xem Roadmap). <strong>Phạm vi:</strong> chỉ lý thuyết và quiz. Lab, video, dữ liệu mẫu và chứng nhận sẽ bổ sung sau.</p><hr><h2 id="workflow-tong-the-—-7-giai-đoan-can-nho" tabindex="-1">Workflow tổng thể — 7 giai đoạn cần nhớ <a class="header-anchor" href="#workflow-tong-the-—-7-giai-đoan-can-nho" aria-label="Permalink to &quot;Workflow tổng thể — 7 giai đoạn cần nhớ&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Thiết kế &amp; DMP → 2. Thu thập → 3. Xử lý &amp; làm sạch</span></span>
<span class="line"><span>→ 4. Chuẩn hóa (CDISC / FHIR / OMOP) → 5. Phân tích &amp; tái lập</span></span>
<span class="line"><span>→ 6. FAIR &amp; chia sẻ → 7. Lưu trữ &amp; hủy an toàn</span></span></code></pre></div><p>Quy tắc xuyên suốt: <strong>quyết định càng sớm càng rẻ</strong>. Một trường dữ liệu không định nghĩa ở bước 1 sẽ thành dữ liệu khuyết, không so sánh được, hoặc không dùng được cho AI ở các giai đoạn sau. DMP không phải thủ tục hành chính — nó là bản hợp đồng về dữ liệu của cả nghiên cứu.</p><p><strong>Bốn lớp ngang:</strong> quản trị dữ liệu; bảo mật và quyền riêng tư; pháp lý và đạo đức; vai trò Data Steward. Cả bốn áp dụng ở mọi giai đoạn của vòng đời dữ liệu, từ lập kế hoạch đến lưu trữ hoặc tiêu hủy; đây không phải một bước chỉ làm ở cuối.</p><table tabindex="0"><thead><tr><th>Giai đoạn / lớp ngang</th><th>Bài học trong khóa này</th></tr></thead><tbody><tr><td>1. Thiết kế &amp; DMP</td><td>Bài 1</td></tr><tr><td>2. Thu thập</td><td>Bài 2</td></tr><tr><td>3. Xử lý &amp; làm sạch</td><td>Bài 4</td></tr><tr><td>4. Chuẩn hóa</td><td>Bài 3</td></tr><tr><td>5. Phân tích &amp; tái lập</td><td>Bài 4 (phần tái lập); chưa có bài riêng trong khóa này</td></tr><tr><td>6. FAIR &amp; chia sẻ</td><td>Bài 5</td></tr><tr><td>7. Lưu trữ &amp; hủy an toàn</td><td>Bài 5 (kết thúc nghiên cứu)</td></tr><tr><td>Lớp ngang: quản trị, Data Steward</td><td>Bài 1</td></tr><tr><td>Lớp ngang: bảo mật, pháp lý, đạo đức</td><td>Bài 6</td></tr></tbody></table><hr>`,10)])])}const u=n(o,[["render",c]]);export{l as __pageData,u as default};
